// Generates the Kovi shared icon module from the SVGs extracted off the live page.
// Source: docs/research/www-kovi-com-br-a550a92b/aluguel-carro-belo-horizonte-a10fa8e0/raw-svgs.json
import { readFile, writeFile } from 'node:fs/promises';

const RESEARCH =
  'docs/research/www-kovi-com-br-a550a92b/aluguel-carro-belo-horizonte-a10fa8e0/raw-svgs.json';
const OUT = 'src/components/sites/www-kovi-com-br-a550a92b/shared/icons.tsx';

// zone -> [componentName, ...] in the order the SVGs appear in that zone
const NAMES = {
  header: ['PhoneIcon'],
  citybar: ['GlobePinIcon', 'ChevronRightIcon'],
  catalog: ['InfoIcon'],
  uber: ['UberPartnerIcon', 'NoCreditCardIcon', 'NegativadosIcon', 'UnlimitedKmIcon'],
  steps: ['StepRegisterIcon', 'StepPaymentIcon', 'StepPickupIcon'],
  faq: ['FaqChevronIcon'],
  footer: [
    'FacebookIcon',
    'YoutubeIcon',
    'InstagramIcon',
    'LinkedinIcon',
    'GooglePlayIcon',
  ],
};

const ATTR = {
  class: 'className',
  'fill-rule': 'fillRule',
  'clip-rule': 'clipRule',
  'stroke-width': 'strokeWidth',
  'stroke-linecap': 'strokeLinecap',
  'stroke-linejoin': 'strokeLinejoin',
  'stroke-miterlimit': 'strokeMiterlimit',
  'stroke-dasharray': 'strokeDasharray',
  'clip-path': 'clipPath',
  'fill-opacity': 'fillOpacity',
  'stroke-opacity': 'strokeOpacity',
  'stop-color': 'stopColor',
  'stop-opacity': 'stopOpacity',
  'xlink:href': 'xlinkHref',
  'xmlns:xlink': 'xmlnsXlink',
  'gradientUnits': 'gradientUnits',
  'gradientTransform': 'gradientTransform',
  'maskUnits': 'maskUnits',
  'mask-type': 'maskType',
};

/** `style="mask-type:luminance"` -> `style={{ maskType: "luminance" }}` */
function inlineStyleToJsx(svg) {
  return svg.replace(/\sstyle="([^"]*)"/g, (_m, decls) => {
    const entries = decls
      .split(';')
      .map((d) => d.trim())
      .filter(Boolean)
      .map((d) => {
        const idx = d.indexOf(':');
        const prop = d.slice(0, idx).trim();
        const value = d.slice(idx + 1).trim();
        const camel = prop.replace(/-([a-z])/g, (_x, c) => c.toUpperCase());
        return `${camel}: ${JSON.stringify(value)}`;
      });
    return entries.length ? ` style={{ ${entries.join(', ')} }}` : '';
  });
}

function toJsx(svg) {
  let out = inlineStyleToJsx(svg);
  for (const [from, to] of Object.entries(ATTR)) {
    out = out.replaceAll(new RegExp(`(\\s)${from}=`, 'g'), `$1${to}=`);
  }
  // self-close void-ish SVG children that came back as <path ...></path>
  out = out.replace(/<(path|circle|rect|line|polygon|polyline|ellipse|stop|use)([^>]*?)><\/\1>/g, '<$1$2/>');
  return out;
}

/** Make the icon inherit size/colour from props instead of hardcoding them. */
function parameterise(svg) {
  // strip the literal width/height off the root <svg> — callers size it
  return svg.replace(/^<svg([^>]*)>/, (_m, attrs) => {
    const cleaned = attrs
      .replace(/\swidth="[^"]*"/, '')
      .replace(/\sheight="[^"]*"/, '')
      .replace(/\sclassName="[^"]*"/, '');
    return `<svg${cleaned} {...props}>`;
  });
}

const raw = JSON.parse(await readFile(RESEARCH, 'utf8'));

const parts = [
  '// AUTO-GENERATED by scripts/gen-icons-www-kovi-com-br-a550a92b.mjs — do not edit by hand.',
  '// Paths are verbatim from https://www.kovi.com.br/aluguel-carro-belo-horizonte',
  '',
  'import type { SVGProps } from "react";',
  '',
  'type IconProps = SVGProps<SVGSVGElement>;',
  '',
];

let count = 0;
for (const [zone, names] of Object.entries(NAMES)) {
  const svgs = raw[zone] ?? [];
  names.forEach((name, i) => {
    const svg = svgs[i];
    if (!svg) {
      throw new Error(`Missing SVG for ${name} (zone ${zone}, index ${i})`);
    }
    const jsx = parameterise(toJsx(svg.html));
    parts.push(
      `export function ${name}(props: IconProps) {`,
      `  return (`,
      `    ${jsx}`,
      `  );`,
      `}`,
      ''
    );
    count += 1;
  });
}

await writeFile(OUT, parts.join('\n'), 'utf8');
console.log(`Wrote ${count} icons to ${OUT}`);
